/**
 * Social platform detection + inline SVG icons.
 *
 * These are plain string helpers (no React) so they can be used both in
 * server components (for the public page, zero-JS) and in admin UI.
 *
 * Brand SVG paths sourced from simple-icons (CC0).
 */

export type SocialPlatform =
  | "instagram" | "tiktok" | "youtube" | "twitter" | "x" | "github"
  | "discord" | "twitch" | "spotify" | "linkedin" | "telegram"
  | "whatsapp" | "email" | "threads" | "bluesky" | "mastodon"
  | "reddit" | "facebook" | "pinterest" | "snapchat" | "patreon"
  | "substack" | "gumroad" | "behance" | "dribbble" | "soundcloud"
  | "bandcamp" | "vimeo" | "signal" | "paypal" | "buymeacoffee"
  | "kofi" | "medium"
  | "applemusic" | "applepodcasts" | "tumblr" | "flickr" | "rss"
  | "steam" | "etsy" | "goodreads" | "wattpad" | "unsplash"
  | "deviantart" | "cashapp" | "venmo" | "line" | "wechat"
  | "vk" | "quora" | "gitlab" | "stackoverflow" | "producthunt"
  | "linktree" | "bento" | "website";

export const SUPPORTED_PLATFORMS: SocialPlatform[] = [
  // `twitter` is intentionally NOT listed: it's a recognized alias (old saved
  // links keep rendering) but "X (Twitter)" and "X" both drew the same X logo,
  // so the picker offered the same icon twice. Detection now maps every
  // twitter.com/x.com URL to the single `x` entry below.
  "website", "instagram", "tiktok", "youtube", "x", "github",
  "discord", "twitch", "spotify", "linkedin", "telegram",
  "whatsapp", "email", "threads", "bluesky", "mastodon",
  "reddit", "facebook", "pinterest", "snapchat", "patreon",
  "substack", "gumroad", "behance", "dribbble", "soundcloud",
  "bandcamp", "vimeo", "signal", "paypal", "buymeacoffee",
  "kofi", "medium",
  "applemusic", "applepodcasts", "tumblr", "flickr", "rss",
  "steam", "etsy", "goodreads", "wattpad", "unsplash",
  "deviantart", "cashapp", "venmo", "line", "wechat",
  "vk", "quora", "gitlab", "stackoverflow", "producthunt",
  "linktree", "bento",
];

const PLATFORM_LABELS: Record<SocialPlatform, string> = {
  website: "Website", instagram: "Instagram", tiktok: "TikTok", youtube: "YouTube",
  twitter: "X (Twitter)", x: "X", github: "GitHub", discord: "Discord",
  twitch: "Twitch", spotify: "Spotify", linkedin: "LinkedIn",
  telegram: "Telegram", whatsapp: "WhatsApp", email: "Email",
  threads: "Threads", bluesky: "Bluesky", mastodon: "Mastodon",
  reddit: "Reddit", facebook: "Facebook", pinterest: "Pinterest",
  snapchat: "Snapchat", patreon: "Patreon", substack: "Substack",
  gumroad: "Gumroad", behance: "Behance", dribbble: "Dribbble",
  soundcloud: "SoundCloud", bandcamp: "Bandcamp", vimeo: "Vimeo",
  signal: "Signal", paypal: "PayPal", buymeacoffee: "Buy Me a Coffee",
  kofi: "Ko-fi", medium: "Medium",
  applemusic: "Apple Music", applepodcasts: "Apple Podcasts",
  tumblr: "Tumblr", flickr: "Flickr", rss: "RSS Feed",
  steam: "Steam", etsy: "Etsy", goodreads: "Goodreads",
  wattpad: "Wattpad", unsplash: "Unsplash", deviantart: "DeviantArt",
  cashapp: "Cash App", venmo: "Venmo", line: "LINE",
  wechat: "WeChat", vk: "VK", quora: "Quora",
  gitlab: "GitLab", stackoverflow: "Stack Overflow",
  producthunt: "Product Hunt", linktree: "Linktree", bento: "Bento",
};

export function getPlatformLabel(platform: SocialPlatform): string {
  return PLATFORM_LABELS[platform] ?? platform;
}

interface Rule {
  platform: SocialPlatform;
  test: (host: string, value: string) => boolean;
}

/** Check if a hostname exactly matches or is a subdomain of the given domain. */
function isHost(host: string, domain: string): boolean {
  return host === domain || host.endsWith("." + domain);
}

const RULES: Rule[] = [
  { platform: "instagram", test: (h) => isHost(h, "instagram.com") },
  { platform: "tiktok", test: (h) => isHost(h, "tiktok.com") },
  { platform: "youtube", test: (h) => isHost(h, "youtube.com") || isHost(h, "youtu.be") },
  { platform: "x", test: (h) => isHost(h, "twitter.com") || isHost(h, "x.com") },
  { platform: "github", test: (h) => isHost(h, "github.com") },
  { platform: "discord", test: (h, v) => isHost(h, "discord.gg") || isHost(h, "discord.com") || v.startsWith("discord:") },
  { platform: "twitch", test: (h) => isHost(h, "twitch.tv") },
  { platform: "spotify", test: (h) => isHost(h, "spotify.com") },
  { platform: "linkedin", test: (h) => isHost(h, "linkedin.com") },
  { platform: "telegram", test: (h, v) => h === "t.me" || h.endsWith(".t.me") || v.startsWith("telegram:") || v.startsWith("tg:") },
  { platform: "whatsapp", test: (h, v) => h === "wa.me" || isHost(h, "whatsapp.com") || v.startsWith("whatsapp:") },
  { platform: "threads", test: (h) => isHost(h, "threads.net") },
  { platform: "bluesky", test: (h) => isHost(h, "bsky.app") || isHost(h, "bsky.social") },
  { platform: "mastodon", test: (h) => isHost(h, "mastodon.social") || isHost(h, "mas.to") || h.endsWith(".mastodon.social") },
  { platform: "reddit", test: (h) => isHost(h, "reddit.com") },
  { platform: "facebook", test: (h) => isHost(h, "facebook.com") || isHost(h, "fb.com") },
  { platform: "pinterest", test: (h) => isHost(h, "pinterest.com") || isHost(h, "pin.it") },
  { platform: "snapchat", test: (h) => isHost(h, "snapchat.com") },
  { platform: "patreon", test: (h) => isHost(h, "patreon.com") },
  { platform: "substack", test: (h) => isHost(h, "substack.com") },
  { platform: "gumroad", test: (h) => isHost(h, "gumroad.com") || isHost(h, "gum.co") },
  { platform: "behance", test: (h) => isHost(h, "behance.net") },
  { platform: "dribbble", test: (h) => isHost(h, "dribbble.com") },
  { platform: "soundcloud", test: (h) => isHost(h, "soundcloud.com") },
  { platform: "bandcamp", test: (h) => isHost(h, "bandcamp.com") },
  { platform: "vimeo", test: (h) => isHost(h, "vimeo.com") },
  { platform: "signal", test: (h, v) => h === "signal.me" || h === "sgnl.me" || v.startsWith("signal:") },
  { platform: "paypal", test: (h) => h === "paypal.me" || isHost(h, "paypal.com") },
  { platform: "buymeacoffee", test: (h) => isHost(h, "buymeacoffee.com") },
  { platform: "kofi", test: (h) => isHost(h, "ko-fi.com") },
  { platform: "medium", test: (h) => isHost(h, "medium.com") },
  { platform: "applemusic", test: (h) => isHost(h, "music.apple.com") },
  { platform: "applepodcasts", test: (h) => isHost(h, "podcasts.apple.com") },
  { platform: "tumblr", test: (h) => isHost(h, "tumblr.com") },
  { platform: "flickr", test: (h) => isHost(h, "flickr.com") || isHost(h, "flic.kr") },
  { platform: "steam", test: (h) => isHost(h, "steamcommunity.com") || isHost(h, "steampowered.com") },
  { platform: "etsy", test: (h) => isHost(h, "etsy.com") },
  { platform: "goodreads", test: (h) => isHost(h, "goodreads.com") },
  { platform: "wattpad", test: (h) => isHost(h, "wattpad.com") },
  { platform: "unsplash", test: (h) => isHost(h, "unsplash.com") },
  { platform: "deviantart", test: (h) => isHost(h, "deviantart.com") },
  { platform: "cashapp", test: (h) => h === "cash.app" || isHost(h, "cashapp.com") },
  { platform: "venmo", test: (h) => h === "venmo.com" || isHost(h, "venmo.com") },
  { platform: "line", test: (h) => h === "line.me" },
  { platform: "wechat", test: (h, v) => isHost(h, "wechat.com") || v.startsWith("weixin:") },
  { platform: "vk", test: (h) => isHost(h, "vk.com") },
  { platform: "quora", test: (h) => isHost(h, "quora.com") },
  { platform: "gitlab", test: (h) => isHost(h, "gitlab.com") },
  { platform: "stackoverflow", test: (h) => isHost(h, "stackoverflow.com") },
  { platform: "producthunt", test: (h) => isHost(h, "producthunt.com") },
  { platform: "linktree", test: (h) => isHost(h, "linktr.ee") },
  { platform: "bento", test: (h) => isHost(h, "bento.me") },
  { platform: "rss", test: (_h, v) => v.includes("/feed") || v.includes("/rss") || v.endsWith(".xml") || v.includes("/atom") },
  { platform: "email", test: (_h, v) => v.startsWith("mailto:") },
];

/**
 * Detect a social platform from a URL or handle string. Returns null when
 * no platform matches.
 */
export function detectPlatform(input: string): SocialPlatform | null {
  if (!input) return null;
  const value = input.trim().toLowerCase();
  for (const rule of RULES) {
    let host = "";
    try {
      host = new URL(value.startsWith("http") ? value : `https://${value}`).hostname;
    } catch {
      host = value;
    }
    if (rule.test(host, value)) return rule.platform;
  }
  return null;
}

/**
 * Minimal, single-colour inline SVG icons for each platform. `currentColor`
 * is used so the icon inherits text colour. Each returns a self-contained
 * `<svg>` markup string sized 24x24.
 *
 * Brand SVG paths sourced from simple-icons (CC0).
 */
function svgFill(d: string): string {
  return `<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="${d}"/></svg>`;
}

